"""Single-variable behavior reweighting; fresh route-isolated velocity2 models."""
from train_structural_prototypes_light512 import *
from torchdata.stateful_dataloader import StatefulDataLoader
class StreamData(pl.LightningDataModule):
 def __init__(self,selection):super().__init__();self.selection=selection
 def train_dataloader(self):return StatefulDataLoader(DiskSamples(self.selection['train']),batch_size=8,shuffle=False,num_workers=0)
 def val_dataloader(self):return StatefulDataLoader(DiskSamples(self.selection['validation']),batch_size=8,shuffle=False,num_workers=0)
def main():
 idle();configure_runtime();out=ROOT/'artifacts/scene-balance-light512';design=json.loads((out/'design.json').read_text());names=[r['file'] for r in design['validation']];scales=json.loads((ROOT/'artifacts/residual-representation-paired128/scale_calibration.json').read_text())['scales_m'];cfg=json.loads((ROOT/'artifacts/structural-prototypes-light512/config.json').read_text());cfg.update(experiment='route_isolated_behavior_reweight_only',input='velocity2,world current_support unchanged',train_steps=512);(out/'config.json').write_text(json.dumps(cfg,indent=2));allstart=time.perf_counter();results=[]
 for seed in [2020,2021]:
  pl.seed_everything(seed);initial=PrototypeJoint(128,2,4,'velocity2','current_support');initial.set_scales(scales);state={k:v.clone() for k,v in initial.state_dict().items()};del initial;traces={}
  for arm in (['representative','balanced'] if seed==2020 else ['balanced','representative']):
   idle();assert time.perf_counter()-allstart<900;pl.seed_everything(seed);folder=out/f'{seed}-{arm}';folder.mkdir(exist_ok=False);sel={'train':design['streams'][str(seed)][arm],'validation':names};assert not set(sel['train'])&set(names);sha=hashlib.sha256(json.dumps(sel,sort_keys=True).encode()).hexdigest();(folder/'selection.json').write_text(json.dumps(sel));task=ProtoTask(cfg,seed,'velocity_only',scales,sha);task.mode=arm;task.settings.update(sampling_arm=arm,route_split=design['held_route_groups']);task.model.load_state_dict(state,strict=True);torch.cuda.empty_cache();torch.cuda.reset_peak_memory_stats();start=time.perf_counter();callbacks=[Status(folder),ModelCheckpoint(dirpath=str(folder),filename='latest',enable_version_counter=False,save_top_k=1,every_n_train_steps=128,save_on_train_epoch_end=False),EpochLatest(folder/'latest.ckpt'),ModelCheckpoint(dirpath=str(folder),filename='best',enable_version_counter=False,monitor='validation_position_diagnostic_m',mode='min',save_top_k=1,save_on_train_epoch_end=False)];trainer=pl.Trainer(accelerator='gpu',devices=1,precision='bf16-mixed',max_steps=512,max_epochs=-1,max_time={'minutes':4},callbacks=callbacks,plugins=[VerifiedCheckpointIO()],logger=TensorBoardLogger(str(ROOT/'logs/tensorboard/v1'),name='scene-balance-light512',version=f'{seed}-{arm}'),num_sanity_val_steps=0,val_check_interval=256,check_val_every_n_epoch=None,gradient_clip_val=1,enable_progress_bar=False,enable_model_summary=False,log_every_n_steps=16);trainer.fit(task,datamodule=StreamData(sel));assert trainer.global_step==512;wall=time.perf_counter()-start;peak=torch.cuda.max_memory_allocated()/2**30;traces[arm]=task.trace;check=torch.load(folder/'latest.ckpt',map_location='cpu',weights_only=False);assert check['global_step']==512;del check;reference=copy.deepcopy(task.model.teacher).cuda().eval();ev=evaluate(task.model,names,reference,True);r={'seed':seed,'arm':arm,'steps':512,'wall_s':wall,'peak_allocated_gib':peak,'eval':ev,'rng_first3':task.trace,'grads':task.grads,'sampling_report':design['stream_reports'][str(seed)][arm]};(folder/'report.json').write_text(json.dumps(r,indent=2));brief={k:v for k,v in r.items() if k not in ['eval','rng_first3','grads']};brief['summary']=ev['summary'];results.append(brief);(out/'summary.partial.json').write_text(json.dumps(results,indent=2));print('RESULT '+json.dumps(brief),flush=True);del task,trainer,reference;gc.collect();torch.cuda.empty_cache()
  assert traces['representative']==traces['balanced'];del state
 (out/'summary.json').write_text(json.dumps({'results':results,'wall_s':time.perf_counter()-allstart,'limits':design['limits'],'steady_stop_train_examples':0,'weights_and_framework_same':True,'paired_noise_first3_equal':True,'collision':None,'closed_loop':False},indent=2));print('DONE')
if __name__=='__main__':main()
